package org.sleepwell.app;
import org.json.*;import java.util.*;

/** Strict private codec, deliberately separate from portable alarm rows. */
final class AlarmDefaultsJson {
    private static final Set<String> NUMBERS=Set.of("smartWindow","volume","rampSeconds","snoozeMinutes","snoozeLimit","awakeCheck","backupMinutes","soundDelaySeconds","vibrationDelaySeconds");
    private static final Set<String> FLAGS=Set.of("vibrate","pin","extraLoud","sunrise","flashlight","shortenSnoozes");
    static String encode(AlarmDefaults defaults){try{JSONObject full=defaults.create(1).json(),settings=new JSONObject();for(String key:NUMBERS)settings.put(key,full.get(key));for(String key:FLAGS)settings.put(key,full.get(key));settings.put("tone",full.getString("tone")).put("routine",full.getJSONArray("routine"));if(full.has("timing"))settings.put("timing",full.getJSONObject("timing"));if(full.has("inputs"))settings.put("inputs",full.getJSONObject("inputs"));if(full.has("toneDisplayName"))settings.put("toneDisplayName",full.getString("toneDisplayName"));return new JSONObject().put("version",1).put("settings",settings).toString();}catch(JSONException impossible){throw new IllegalStateException(impossible);}}
    static AlarmDefaults decode(String text){try{if(text==null||text.length()>32768)throw new JSONException("Missing or oversized defaults");JSONObject root=new JSONObject(text);if(root.length()!=2||!(root.get("version") instanceof Number)||root.getDouble("version")!=1)throw new JSONException("Unsupported defaults");JSONObject settings=root.getJSONObject("settings");Set<String> allowed=new HashSet<>(NUMBERS);allowed.addAll(FLAGS);allowed.addAll(Set.of("tone","routine","toneDisplayName","inputs","timing"));for(Iterator<String> keys=settings.keys();keys.hasNext();)if(!allowed.contains(keys.next()))throw new JSONException("Unexpected default field");for(String key:NUMBERS){Object raw=settings.get(key);if(!(raw instanceof Number)||!Double.isFinite(((Number)raw).doubleValue())||((Number)raw).doubleValue()!=Math.rint(((Number)raw).doubleValue())||((Number)raw).doubleValue()<Integer.MIN_VALUE||((Number)raw).doubleValue()>Integer.MAX_VALUE)throw new JSONException("Invalid default number");}for(String key:FLAGS)if(!(settings.get(key) instanceof Boolean))throw new JSONException("Invalid default switch");if(!(settings.get("tone") instanceof String)||settings.has("toneDisplayName")&&!(settings.get("toneDisplayName") instanceof String))throw new JSONException("Invalid sound");ChallengeRoutineJson.decode(settings.getJSONArray("routine"));Alarm alarm=Alarm.read(settings);return new AlarmDefaults(alarm);}catch(JSONException|IllegalArgumentException invalid){throw new IllegalArgumentException("Saved alarm defaults are invalid.",invalid);}}
}
